def transform(grid):
    h, w = len(grid), len(grid[0])

    # Horizontal stripe task: clue row indices assign colors to residues.
    if all(len(set(row)) == 1 for row in grid):
        known = [(r, row[0]) for r, row in enumerate(grid) if row[0] != 0]
        period = len(known)
        phases = {}
        for r, color in known:
            phase = r % period
            if phase in phases and phases[phase] != color:
                raise ValueError("inconsistent horizontal stripe clues")
            phases[phase] = color
        return [[phases[r % period]] * w for r in range(h)]

    # Diagonal stripe tasks may run along either diagonal orientation. Pick
    # the coordinate whose clue lines and periodic phases are consistent.
    for coord in (lambda r, c: c - r, lambda r, c: r + c):
        marks = {}
        valid = True
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    k = coord(r, c)
                    if k in marks and marks[k] != color:
                        valid = False
                        break
                    marks[k] = color
            if not valid:
                break
        if not valid or not marks:
            continue
        period = len(marks)
        phases = {}
        for k, color in marks.items():
            phase = k % period
            if phase in phases and phases[phase] != color:
                valid = False
                break
            phases[phase] = color
        if valid and len(phases) == period:
            return [[phases[coord(r, c) % period] for c in range(w)] for r in range(h)]
    raise ValueError("could not infer stripe pattern")

